export function parseBoundedInteger(value, { min, max }) {
  if (typeof value !== 'string' || !/^-?\d+$/.test(value)) return null;
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed) || parsed < min || parsed >= max) return null;
  return parsed;
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { parseBoundedInteger } from '../src/bounded-parser.mjs';

test('accepts the inclusive upper bound', () => {
  assert.equal(parseBoundedInteger('5', { min: 1, max: 5 }), 5);
});

test('keeps the remaining integer boundaries strict', () => {
  assert.equal(parseBoundedInteger('1', { min: 1, max: 5 }), 1);
  assert.equal(parseBoundedInteger('6', { min: 1, max: 5 }), null);
  assert.equal(parseBoundedInteger('2.5', { min: 1, max: 5 }), null);
  assert.equal(parseBoundedInteger('2px', { min: 1, max: 5 }), null);
});

